pub fn begins_with_p(mut cs: Chars, mut pat: Chars) -> bool {
    loop {
        if null_p(pat) {
            return true;
        } else {
            if not(null_p(cs)) {
                if char_eq_p(car(cs), car(pat)) {
                    (cs, pat) = (cdr(cs), cdr(pat));
                    continue;
                } else {
                    return false;
                }
            } else {
                return false;
            }
        }
    }
}

/// What follows the first `in staged code: ` of a refusal; all of it if none.
pub fn after_said(mut cs: Chars, mut pat: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return nil::<char>();
        } else if begins_with_p(cs, pat) {
            return drop_chars(cs, size(pat));
        } else {
            cs = cdr(cs);
            continue;
        }
    }
}

