    staged_sum_x(str_lit!("failed"), staged_product_x(kayak_rt::heap_cons(k, kayak_rt::heap_cons(msg, kayak_rt::heap_cons(fix(0i64), kayak_rt::heap_cons(fix(0i64), kayak_rt::nil()))))))
