impl kayak_rt::Visit for Rpe {
    fn visit<'a>(&'a self, t: &mut kayak_rt::Tracer<'a>) {
        match self {
            Self::Rpe(f0, f1, f2) => { kayak_rt::Trace::trace(*f0, t); kayak_rt::Trace::trace(*f1, t); kayak_rt::Trace::trace(*f2, t); }
        }
    }
}

pub fn rpe(f0: Str, f1: RpNodes, f2: List<Symbol>) -> kayak_rt::Handle<'static, Rpe> {
    kayak_rt::heap_alloc(Rpe::Rpe(f0, f1, f2))
}

pub fn rp_max_slot(mut ns: RpNodes, mut m: Int) -> Int {
    loop {
        if null_p(ns) {
            return m;
        } else {
            (ns, m) = (cdr(ns), if _gt(car(ns).0, m) {
                car(ns).0
            } else {
                m
            });
            continue;
        }
    }
}

pub fn rp_index_in(mut xs: Strings, mut n: Str, mut i: Int) -> Int {
    loop {
        if null_p(xs) {
            return int_lit(-1);
        } else if string_eq_p(car(xs), n) {
            return i;
        } else {
            (xs, i) = (cdr(xs), _plus(i, int_lit(1)));
            continue;
        }
    }
}

/// An evidence's operand, its nodes `off` past, its holes by name in `all`.
pub fn rp_moved(a: RpOperand, off: Int, own: List<Symbol>, all: Strings) -> RpOperand {
    let tagcase_ = a;
    let tag_ = kayak_rt::sum_tag(tagcase_);
    if tag_ == const { kayak_rt::tag_hash("node") } {
        let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
        the::<RpOperand>(kayak_rt::sum_new::<Int>(const { kayak_rt::tag_hash("node") }, "node", _plus(j, off)))
    } else if tag_ == const { kayak_rt::tag_hash("bound") } {
        let p: Product_11_12<Int, Int> = kayak_rt::sum_payload::<Product_11_12<Int, Int>>(tagcase_);
        the::<RpOperand>(kayak_rt::sum_new::<Product_11_12<Int, Int>>(const { kayak_rt::tag_hash("bound") }, "bound", Product_11_12(_plus(p.0, off), p.1)))
    } else if tag_ == const { kayak_rt::tag_hash("hole") } {
        let h: Int = kayak_rt::sum_payload::<Int>(tagcase_);
        the::<RpOperand>(kayak_rt::sum_new::<Int>(const { kayak_rt::tag_hash("hole") }, "hole", rp_index_in(all, nth_symbol(own, h), int_lit(0))))
    } else {
        let other = tagcase_;
        a
    }
}

pub fn rp_evidence_at(mut es: List<kayak_rt::Handle<'static, Rpe>>, mut n: Str) -> List<kayak_rt::Handle<'static, Rpe>> {
    loop {
        if null_p(es) {
            return nil::<kayak_rt::Handle<'static, Rpe>>();
        } else if {
            let tagcase_ = car(es);
            match *tagcase_ {
                Rpe::Rpe(m, ns, hs) => {
                    string_eq_p(m, n)
                }
            }
        } {
            return kayak_rt::heap_cons(car(es), kayak_rt::nil());
        } else {
            es = cdr(es);
            continue;
        }
    }
}

// Each evidence placed: its offset, and its root's operand moved.
pub enum Rpp {
    Rpp(Str, Int, RpNodes, List<Symbol>),
}

impl kayak_rt::Visit for Rpp {
    fn visit<'a>(&'a self, t: &mut kayak_rt::Tracer<'a>) {
        match self {
            Self::Rpp(f0, f1, f2, f3) => { kayak_rt::Trace::trace(*f0, t); kayak_rt::Trace::trace(*f1, t); kayak_rt::Trace::trace(*f2, t); kayak_rt::Trace::trace(*f3, t); }
        }
    }
}

pub fn rpp(f0: Str, f1: Int, f2: RpNodes, f3: List<Symbol>) -> kayak_rt::Handle<'static, Rpp> {
    kayak_rt::heap_alloc(Rpp::Rpp(f0, f1, f2, f3))
}

pub fn rp_placed(es: List<kayak_rt::Handle<'static, Rpe>>, off: Int) -> List<kayak_rt::Handle<'static, Rpp>> {
    if null_p(es) {
        nil::<kayak_rt::Handle<'static, Rpp>>()
    } else {
        let tagcase_ = car(es);
        match *tagcase_ {
            Rpe::Rpe(n, ns, hs) => {
                kayak_rt::heap_cons(rpp(n, off, ns, hs), rp_placed(cdr(es), _plus(off, _plus(rp_max_slot(ns, int_lit(0)), int_lit(1)))))
            }
        }
    }
}

pub fn rp_placed_at(mut ps: List<kayak_rt::Handle<'static, Rpp>>, mut n: Str) -> List<kayak_rt::Handle<'static, Rpp>> {
    loop {
        if null_p(ps) {
            return nil::<kayak_rt::Handle<'static, Rpp>>();
        } else if {
            let tagcase_ = car(ps);
            match *tagcase_ {
                Rpp::Rpp(m, off, ns, hs) => {
                    string_eq_p(m, n)
                }
            }
        } {
            return kayak_rt::heap_cons(car(ps), kayak_rt::nil());
        } else {
            ps = cdr(ps);
            continue;
        }
    }
}

/// What evidence is of: its root's one operand, moved.
pub fn rp_of_evidence(p: kayak_rt::Handle<'static, Rpp>, all: Strings) -> RpOperand {
    let tagcase_ = p;
    match *tagcase_ {
        Rpp::Rpp(n, off, ns, hs) => {
            let root = rp_node_at(ns, int_lit(0));
            if null_p(root) {
                the::<RpOperand>(kayak_rt::sum_new::<Int>(const { kayak_rt::tag_hash("int") }, "int", int_lit(0)))
            } else {
                rp_moved(car(car(root).4), off, hs, all)
            }
        }
    }
}

/// A node's operands, each filled hole what its evidence is of; in a set,
/// a set's members spliced.
pub fn rp_filled_args(r#as: RpOperands, set: bool, holes: List<Symbol>, ps: List<kayak_rt::Handle<'static, Rpp>>, all: Strings, ns_all: RpNodes) -> RpOperands {
    if null_p(r#as) {
        nil::<kayak_rt::Sum>()
    } else {
        let rest = rp_filled_args(cdr(r#as), set, holes, ps, all, ns_all);
        let tagcase_ = car(r#as);
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("hole") } {
            let h: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            let found = rp_placed_at(ps, nth_symbol(holes, h));
            if null_p(found) {
                kayak_rt::heap_cons(the::<RpOperand>(kayak_rt::sum_new::<Int>(const { kayak_rt::tag_hash("hole") }, "hole", rp_index_in(all, nth_symbol(holes, h), int_lit(0)))), rest)
            } else {
                let of = rp_of_evidence(car(found), all);
                let tagcase_ = of;
                let tag_ = kayak_rt::sum_tag(tagcase_);
                if tag_ == const { kayak_rt::tag_hash("node") } {
                    let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                    let n = rp_node_at(ns_all, j);
                    if (set && not(null_p(n)) && car(n).2) {
                        onto(car(n).4, rest)
                    } else {
                        kayak_rt::heap_cons(of, rest)
                    }
                } else {
                    let z = tagcase_;
                    kayak_rt::heap_cons(of, rest)
                }
            }
        } else {
            let other = tagcase_;
            kayak_rt::heap_cons(car(r#as), rest)
        }
    }
}

pub enum Rpalias {
    Rpalias(Int, RpOperand),
}

impl kayak_rt::Visit for Rpalias {
    fn visit<'a>(&'a self, t: &mut kayak_rt::Tracer<'a>) {
        match self {
            Self::Rpalias(f0, f1) => { kayak_rt::Trace::trace(*f0, t); kayak_rt::Trace::trace(*f1, t); }
        }
    }
}

pub fn rpalias(f0: Int, f1: RpOperand) -> kayak_rt::Handle<'static, Rpalias> {
    kayak_rt::heap_alloc(Rpalias::Rpalias(f0, f1))
}

/// Each `var` node of `before` over a hole, which `after`, the same nodes
/// filled, fills: its slot, and its filler.
pub fn rp_var_aliases(before: RpNodes, after: RpNodes) -> List<kayak_rt::Handle<'static, Rpalias>> {
    if (null_p(before) || null_p(after)) {
        nil::<kayak_rt::Handle<'static, Rpalias>>()
    } else {
        let (rest, x) = (rp_var_aliases(cdr(before), cdr(after)), car(before));
        if (string_eq_p(symbol_to_string(x.1), str_lit!("var")) && i64_eq(size(x.4), 1i64) && {
            let tagcase_ = car(x.4);
            let tag_ = kayak_rt::sum_tag(tagcase_);
            if tag_ == const { kayak_rt::tag_hash("hole") } {
                let h: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                true
            } else {
                let other = tagcase_;
                false
            }
        } && not({
            let tagcase_ = car(car(after).4);
            let tag_ = kayak_rt::sum_tag(tagcase_);
            if tag_ == const { kayak_rt::tag_hash("hole") } {
                let h: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                true
            } else {
                let other = tagcase_;
                false
            }
        })) {
            kayak_rt::heap_cons(rpalias(x.0, car(car(after).4)), rest)
        } else {
            rest
        }
    }
}

pub fn rp_aliased(mut als: List<kayak_rt::Handle<'static, Rpalias>>, mut a: RpOperand) -> RpOperand {
    loop {
        let tagcase_ = a;
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("node") } {
            let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            if null_p(als) {
                return a;
            } else if {
                let tagcase_ = car(als);
                match *tagcase_ {
                    Rpalias::Rpalias(k, f) => {
                        _eq(k, j)
                    }
                }
            } {
                let tagcase_ = car(als);
                match *tagcase_ {
                    Rpalias::Rpalias(k, f) => {
                        return f;
                    }
                }
            } else {
                als = cdr(als);
                continue;
            }
        } else {
            let other = tagcase_;
            return a;
        }
    }
}

/// Rep `main`'s nodes, its holes filled from evidence `es`.
pub fn rp_filled(main: kayak_rt::Handle<'static, Rexp>, es: List<kayak_rt::Handle<'static, Rpe>>) -> kayak_rt::Handle<'static, Rexp> {
    let tagcase_ = main;
    match *tagcase_ {
        Rexp::Rexp(ns, hs, root, d) => {
            let ps = rp_placed(es, _plus(rp_max_slot(ns, int_lit(0)), int_lit(1)));
            let left = filter(kayak_rt::as_proc(kayak_rt::closure1s((ps,), |(ps,), h: Str| {
                null_p(rp_placed_at(ps, h))
            })), hs);
            let theirs = concat(map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), p: kayak_rt::Handle<'static, Rpp>| {
                let tagcase_ = p;
                match *tagcase_ {
                    Rpp::Rpp(n, off, ens, ehs) => {
                        map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), y: Symbol| {
                            symbol_to_string(y)
                        })), ehs)
                    }
                }
            })), ps));
            let all = onto(left, filter(kayak_rt::as_proc(kayak_rt::closure1s((left,), |(left,), h: Str| {
                not(string_member_p(h, left))
            })), theirs));
            let moved = concat(map(kayak_rt::as_proc(kayak_rt::closure1s((all,), |(all,), p: kayak_rt::Handle<'static, Rpp>| {
                let tagcase_ = p;
                match *tagcase_ {
                    Rpp::Rpp(n, off, ens, ehs) => {
                        map(kayak_rt::as_proc(kayak_rt::closure1s((all, off, ehs,), |(all, off, ehs,), x: RpNode| {
                            Product_11_12_13_14_15(_plus(x.0, off), x.1, x.2, x.3, map(kayak_rt::as_proc(kayak_rt::closure1s((all, off, ehs,), |(all, off, ehs,), a: RpOperand| {
                                rp_moved(a, off, ehs, all)
                            })), x.4))
                        })), ens)
                    }
                }
            })), ps));
            let holes = map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), h: Str| {
                string_to_symbol(h)
            })), hs);
            let filled = map(kayak_rt::as_proc(kayak_rt::closure1s((ps, all, moved, holes,), |(ps, all, moved, holes,), x: RpNode| {
                Product_11_12_13_14_15(x.0, x.1, x.2, x.3, rp_filled_args(x.4, x.2, holes, ps, all, moved))
            })), ns);
            let aliases = rp_var_aliases(ns, filled);
            let mine = map(kayak_rt::as_proc(kayak_rt::closure1s((aliases,), |(aliases,), x: RpNode| {
                Product_11_12_13_14_15(x.0, x.1, x.2, x.3, map(kayak_rt::as_proc(kayak_rt::closure1s((aliases,), |(aliases,), a: RpOperand| {
                    rp_aliased(aliases, a)
                })), x.4))
            })), filled);
            rexp(onto(mine, moved), all, {
                let tagcase_ = rp_aliased(aliases, the::<RpOperand>(kayak_rt::sum_new::<Int>(const { kayak_rt::tag_hash("node") }, "node", root)));
                let tag_ = kayak_rt::sum_tag(tagcase_);
                if tag_ == const { kayak_rt::tag_hash("node") } {
                    let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
                    j
                } else {
                    let other = tagcase_;
                    root
                }
            }, d)
        }
    }
}

pub fn rp_same_p(a: RpOperand, b: RpOperand) -> bool {
    let tagcase_ = a;
    let tag_ = kayak_rt::sum_tag(tagcase_);
    if tag_ == const { kayak_rt::tag_hash("node") } {
        let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
        let tagcase_ = b;
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("node") } {
            let k: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            _eq(j, k)
        } else {
            let other = tagcase_;
            false
        }
    } else if tag_ == const { kayak_rt::tag_hash("hole") } {
        let j: Int = kayak_rt::sum_payload::<Int>(tagcase_);
        let tagcase_ = b;
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("hole") } {
            let k: Int = kayak_rt::sum_payload::<Int>(tagcase_);
            _eq(j, k)
        } else {
            let other = tagcase_;
            false
        }
    } else if tag_ == const { kayak_rt::tag_hash("bound") } {
        let p: Product_11_12<Int, Int> = kayak_rt::sum_payload::<Product_11_12<Int, Int>>(tagcase_);
        let tagcase_ = b;
        let tag_ = kayak_rt::sum_tag(tagcase_);
        if tag_ == const { kayak_rt::tag_hash("bound") } {
            let q: Product_11_12<Int, Int> = kayak_rt::sum_payload::<Product_11_12<Int, Int>>(tagcase_);
            (_eq(p.0, q.0) && _eq(p.1, q.1))
        } else {
            let other = tagcase_;
            false
        }
    } else {
        let other = tagcase_;
        false
    }
}

// A canonical rep's nodes, a set's members each once (Fixpt's `fill::dedup`).
pub fn rp_once(mut r#as: RpOperands) -> RpOperands {
    loop {
        if null_p(r#as) {
            return nil::<kayak_rt::Sum>();
        } else if any_p(kayak_rt::as_proc(kayak_rt::closure1s((r#as,), |(r#as,), b: RpOperand| {
            rp_same_p(car(r#as), b)
        })), cdr(r#as)) {
            r#as = cdr(r#as);
            continue;
        } else {
            return kayak_rt::heap_cons(car(r#as), rp_once(cdr(r#as)));
        }
    }
}

// Evidence's words given: each a rep's binary form, the variable it is for
// named, in the order `names` says.
pub fn evidence_given(prod: i64, names: Strings, i: i64) -> List<kayak_rt::Handle<'static, Rpe>> {
    if null_p(names) {
        nil::<kayak_rt::Handle<'static, Rpe>>()
    } else {
        let got = rep_nodes(heap_kfx_bytes(slot_of(prod, i64_plus(i, 2i64))), nil::<Str>());
        kayak_rt::heap_cons(rpe(car(names), got.0, got.1), evidence_given(prod, cdr(names), i64_plus(i, 1i64)))
    }
}

// A region a variable names, given no evidence: one of its own, named
// afresh, `%region-N`, never another (Fixpt's rule).
#[inline]
pub fn fresh_regions() -> Ref<i64> {
    kayak_rt::kept_constant!(ONCE: Ref<i64>);
    once(&ONCE, || {
        kayak_rt::heap_new(0i64)
    })
}

pub fn fresh_evidence_x(mut holes: Strings, mut named: Strings) -> List<kayak_rt::Handle<'static, Rpe>> {
    loop {
        if null_p(holes) {
            return nil::<kayak_rt::Handle<'static, Rpe>>();
        } else if (not(has_prefix_p(car(holes), str_lit!("'"))) || string_member_p(car(holes), named)) {
            holes = cdr(holes);
            continue;
        } else {
            let k = get(fresh_regions());
            set(fresh_regions(), i64_plus(k, 1i64));
            return kayak_rt::heap_cons(rpe(car(holes), kayak_rt::heap_cons(Product_11_12_13_14_15(int_lit(0), symbol_lit(str_lit!("evidence")), false, nil::<Symbol>(), kayak_rt::heap_cons(the::<RpOperand>(kayak_rt::sum_new::<Int>(const { kayak_rt::tag_hash("node") }, "node", int_lit(1))), kayak_rt::nil())), kayak_rt::heap_cons(Product_11_12_13_14_15(int_lit(1), symbol_lit(str_lit!("rconst")), false, nil::<Symbol>(), kayak_rt::heap_cons(the::<RpOperand>(kayak_rt::sum_new::<Symbol>(const { kayak_rt::tag_hash("sym") }, "sym", string_to_symbol(string_append(str_lit!("%region-"), i64_to_string(k))))), kayak_rt::nil())), kayak_rt::nil())), nil::<Symbol>()), fresh_evidence_x(cdr(holes), named));
        }
    }
}

/// Rep `rep`'s binary form, its holes filled from the evidence `given`
/// holds, for the variables `names` names: canonical, each set's members
/// once.
pub fn rep_filled_x(rep: i64, given: i64, names: Str) -> Bytes {
    let got = rep_nodes(heap_kfx_bytes(rep), nil::<Str>());
    let main = rexp(got.0, map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), y: Symbol| {
        symbol_to_string(y)
    })), got.1), int_lit(0), str_lit!(""));
    let named = spaced_words(names);
    let es = onto(evidence_given(given, named, 0i64), fresh_evidence_x(map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), y: Symbol| {
        symbol_to_string(y)
    })), got.1), named));
    let canonical = kayak_rt::closure1s((), |(), r: kayak_rt::Handle<'static, Rexp>| {
        let tagcase_ = r;
        match *tagcase_ {
            Rexp::Rexp(ns, hs, root, d) => {
                the::<Bytes>(rep_of_nodes(ns, map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), h: Str| {
                    string_to_symbol(h)
                })), hs), root))
            }
        }
    });
    let b = canonical.call(rp_filled(main, es));
    let again = rep_nodes(b, nil::<Str>());
    canonical.call(rexp(map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), x: RpNode| {
        if x.2 {
            Product_11_12_13_14_15(x.0, x.1, true, x.3, rp_once(x.4))
        } else {
            x
        }
    })), again.0), map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), y: Symbol| {
        symbol_to_string(y)
    })), again.1), int_lit(0), str_lit!("")))
}

/// A rep's binary form, a bytevector of the heap, from the text of its
/// nodes the checker noted (`stage-rep`), as the engine's loading makes
/// it (C305): tier 1's `stage` and `%reify` (C337, C339).
pub fn rep_of_text_x(text: Str) -> i64 {
    let tagcase_ = rp_nodes_of_text(text);
    match *tagcase_ {
        Rexp::Rexp(ns, hs, root, d) => {
            kfx_bytes_heap_x(the::<Bytes>(rep_of_nodes(ns, map(kayak_rt::as_proc(kayak_rt::closure1s((), |(), h: Str| {
                string_to_symbol(h)
            })), hs), root)))
        }
    }
}

// `(%reify given REP names)`: evidence, its rep filled.
#[inline]
pub fn reify_run_x(given: i64, rep: i64, names: i64) -> i64 {
    kfx_bytes_heap_x(rep_filled_x(rep, given, string_text(names)))
}

// Sessions (C310; Fixpt's `docs/fx26.md`, "Sessions", and its
// `sessions.rs`, lowered): definitions that last between pieces of code a
// program stages against a module. A session's state is the checker's
// environment of the standard one and the session's own definitions, its
// globals, past the program's, and its definitions' forms, which the
// redefinition rules of the `--check` driver (C202) read: a definition
// again at a type its users can take assigns its global; at another,
// `shadow` makes it a new one, what used the old keeping it, and `rerun`
// checks the users again, each that checks run again, the rest broken.
// The session, a vector `#(m index)`, names its state by its index here,
// made at its first use, when the module's type is known: a global holding
// `m`, and one for each of `m`'s values, which the session's own may
// shadow; defined again as a new global, `fx26-session-K:NAME:2`, ... (C313).
// A pending definition is `#(session index)`, its index among
// `pendings`. Reading a session's global is reading the session, which its
// forms' types say (`(read r)`), not part of the code's `E`: the checker's
// `%session` mark (`naming-effs`).

// A list of the heap of strings `ns`, in order (a redefinition's users).
#[inline]
pub fn staged_strings_x(ns: Strings) -> i64 {
    if null_p(ns) {
        v_null()
    } else {
        cons_x(make_string_x(car(ns)), staged_strings_x(cdr(ns)))
    }
}

